import math


def cheapest_within(quotes, src, dst, k):
    cost = {src: 0}
    for _ in range(k + 1):
        new = dict(cost)
        for a, b, bp in quotes:
            if a in cost and cost[a] + bp < new.get(b, math.inf):
                new[b] = cost[a] + bp
        cost = new
    return cost.get(dst, -1)

def count_clients(records):
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    owner = {}
    groups = len(records)
    for i, ids in enumerate(records):
        for key in ids:
            if key in owner:
                ra, rb = find(i), find(owner[key])
                if ra != rb:
                    parent[ra] = rb
                    groups -= 1
            else:
                owner[key] = i
    return groups

import heapq


def count_cheapest(links, src, dst):
    adj = {}
    for a, b, fee in links:
        adj.setdefault(a, []).append((b, fee))
    cost = {src: 0}
    ways = {src: 1}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > cost[u]:
            continue                # a stale entry: u left the heap earlier
        if u == dst:
            return d, ways[u]       # every cheaper venue is done, so ways[u] is final
        for v, fee in adj.get(u, []):
            nd = d + fee
            if v not in cost or nd < cost[v]:
                cost[v] = nd        # a cheaper route: the old count is void
                ways[v] = ways[u]
                heapq.heappush(heap, (nd, v))
            elif nd == cost[v]:
                ways[v] += ways[u]  # a tie: every cheapest route to u extends
    return None, 0

