def _venue_rng(seed):
    state = [seed]
    def rnd(k):
        state[0] = (state[0] * 6364136223846793005 + 1442695040888963407) % 18446744073709551616
        return (state[0] >> 33) % k
    return rnd


def venue_web(n=1000, m=6000, seed=5):
    rnd = _venue_rng(seed)
    names = ['V%04d' % i for i in range(n)]
    seen, links = set(), []
    while len(links) < m:
        a, b = rnd(n), rnd(n)
        if a != b and (a, b) not in seen:
            seen.add((a, b))
            links.append((names[a], names[b], 1 + rnd(2)))
    return links


def venue_ladder(layers=60, width=5, seed=3):
    rnd = _venue_rng(seed)
    links = []
    for i in range(layers):
        for a in range(width):
            for b in range(width):
                links.append(('L%02d_%d' % (i, a), 'L%02d_%d' % (i + 1, b), 1 + rnd(3)))
    return links
